import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const _=JSON.parse('{"title":"导学 | 实验说明&学习指南","description":"","frontmatter":{},"headers":[{"level":3,"title":"课程实验说明","slug":"课程实验说明","link":"#课程实验说明","children":[]},{"level":3,"title":"问题定位思路","slug":"问题定位思路","link":"#问题定位思路","children":[]},{"level":3,"title":"网络诊断常用工具","slug":"网络诊断常用工具","link":"#网络诊断常用工具","children":[]}],"relativePath":"网络架构实战课/导学｜实验说明&学习指南.md","filePath":"网络架构实战课/导学｜实验说明&学习指南.md","lastUpdated":1795559478000}'),s={name:"网络架构实战课/导学｜实验说明&学习指南.md"};function r(E,e,l,p,o,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="导学-实验说明-学习指南" tabindex="-1">导学 | 实验说明&amp;学习指南 <a class="header-anchor" href="#导学-实验说明-学习指南" aria-label="Permalink to &quot;导学 | 实验说明&amp;学习指南&quot;">​</a></h1><p>你好，我是谢友鹏。</p><p>工欲善其事，必先利其器。开篇词里我曾提过课程里会有很多动手实验环节。</p><p>这节课，我们先来看看后续课程的实验环境要如何搭建。之后，我也想分享一下实战调试和网络诊断的思路和常用工具，为后续的实战环节打好基础。</p><h3 id="课程实验说明" tabindex="-1">课程实验说明 <a class="header-anchor" href="#课程实验说明" aria-label="Permalink to &quot;课程实验说明&quot;">​</a></h3><p>课程中的实验将在 VMware Fusion 环境下进行，通过加载 ubuntu-24.04.1-live-server-amd64.iso 镜像来模拟实际的网络架构和问题解决过程。</p><p>即使你使用其他虚拟机环境，课程内容也同样适用。但如果你是“网络”领域的新手，那么推荐你使用任意的虚拟机软件加载本课程一样的镜像来做实验，这样可以避免一些如命令行之类的差异，阻碍你进行实战。</p><h3 id="问题定位思路" tabindex="-1">问题定位思路 <a class="header-anchor" href="#问题定位思路" aria-label="Permalink to &quot;问题定位思路&quot;">​</a></h3><p>实战里遇到问题要保持积极心态，相信“遇到问题的时候就是成长的时候”。我画了一张图，帮你梳理一下定位问题的思路。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25AF%25BC%25E5%25AD%25A6/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25AF%25BC%25E5%25AD%25A6/1.png" alt=""></a></p><p>遇到问题时，我们首先需要收集足够的信息，包括日志、统计数据、抓包结果、探测信息以及系统采集的数据等一切有用的素材。</p><p>接下来，分析这些信息，寻找其中的规律。例如，可以清洗数据，查看问题是否集中在某一台机器，或问题发生的时间是否有固定的间隔，或者是否只有当数据超过某个阈值时问题才会发生。根据这些分析，可以形成初步的假设——无论是对问题根源的推测，还是对可能故障区域的假设，例如假设是传输层的问题，或者是系统的故障。</p><p>然后，对假设进行验证。如果验证通过，就可以定位问题的根本原因；如果验证失败，则需回到数据收集阶段，重新审视并修正假设，直到找到准确的答案。</p><p>这个问题定位的过程，表明了信息收集方法和理论知识的重要性。掌握更多的信息收集手段和扎实的理论基础，将有助于你做出更准确的假设。而通过不断的假设和验证，不仅能解决眼前的问题，还能加深对理论的理解和应用，形成一个良性循环。因此，培养系统化的思维习惯和方法论，是解决问题的关键所在。</p><h3 id="网络诊断常用工具" tabindex="-1">网络诊断常用工具 <a class="header-anchor" href="#网络诊断常用工具" aria-label="Permalink to &quot;网络诊断常用工具&quot;">​</a></h3><p>我整理了一些常用的信息收集命令，并列成了表格。你不需要死记硬背这些命令，课程中会经常用到它们，熟悉之后自然就会记住。即便忘了也不用担心，网络如此发达，你随时都能找到相关资料。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25AF%25BC%25E5%25AD%25A6/2.jpeg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/%25E5%25AF%25BC%25E5%25AD%25A6/2.jpeg" alt=""></a></p><p>比起记住每个命令的具体用法，更重要的是知道可以查看哪些信息。</p><p>举个例子，知道可以对 CPU 采样这件事，远比记住 perf 命令的详细用法要更重要。因为一旦你知道这个事情，在遇到性能问题时候就能想起来收集这方面的信息，至于如何操作，手册上有详细说明，网上也有很多教程和解决方案。因此，我建议你可以先快速浏览一下这些命令，了解它们的作用，以便在遇到问题时能有个印象。</p><p>接下来，我们就要进入正式的课程学习啦，一起加油吧！</p>',20)])])}const u=t(s,[["render",r]]);export{_ as __pageData,u as default};
